INSERT INTO public.gita_verses (id, chapter_number, verse_number, verse_order, external_id, sanskrit, transliteration, word_meanings, word_meanings_raw) VALUES
('a05fd1d0-d6a1-5e67-8a15-4d7f96560484'::uuid, 17, 6, 601, 601, 'कर्षयन्तः शरीरस्थं भूतग्राममचेतसः।मां चैवान्तःशरीरस्थं तान्विद्ध्यासुरनिश्चयान्।।17.6।।', 'karṣhayantaḥ śharīra-sthaṁ bhūta-grāmam achetasaḥ
māṁ chaivāntaḥ śharīra-sthaṁ tān viddhy āsura-niśhchayān', '[{"word":"karṣhayantaḥ","meaning":"torment"},{"word":"śharīra","meaning":"stham—within the body"},{"word":"bhūta","meaning":"grāmam—elements of the body"},{"word":"achetasaḥ","meaning":"senseless"},{"word":"mām","meaning":"me"},{"word":"cha","meaning":"and"},{"word":"eva","meaning":"even"},{"word":"antaḥ","meaning":"within"},{"word":"śharīra","meaning":"stham—dwelling in the body"},{"word":"tān","meaning":"them"},{"word":"viddhi","meaning":"know"},{"word":"āsura","meaning":"niśhchayān—of demoniacal resolves"}]'::jsonb, 'karṣhayantaḥ—torment; śharīra-stham—within the body; bhūta-grāmam—elements of the body; achetasaḥ—senseless; mām—me; cha—and; eva—even; antaḥ—within; śharīra-stham—dwelling in the body; tān—them; viddhi—know; āsura-niśhchayān—of demoniacal resolves'),
('a889f697-d314-5b0d-8669-0d135b72ef5e'::uuid, 17, 7, 602, 602, 'आहारस्त्वपि सर्वस्य त्रिविधो भवति प्रियः।यज्ञस्तपस्तथा दानं तेषां भेदमिमं श्रृणु।।17.7।।', 'āhāras tv api sarvasya tri-vidho bhavati priyaḥ
yajñas tapas tathā dānaṁ teṣhāṁ bhedam imaṁ śhṛiṇu', '[{"word":"āhāraḥ","meaning":"food"},{"word":"tu","meaning":"indeed"},{"word":"api","meaning":"even"},{"word":"sarvasya","meaning":"of all"},{"word":"tri","meaning":"vidhaḥ—of three kinds"},{"word":"bhavati","meaning":"is"},{"word":"priyaḥ","meaning":"dear"},{"word":"yajñaḥ","meaning":"sacrifice"},{"word":"tapaḥ","meaning":"austerity"},{"word":"tathā","meaning":"and"},{"word":"dānam","meaning":"charity"},{"word":"teṣhām","meaning":"of them"},{"word":"bhedam","meaning":"distinctions"},{"word":"imam","meaning":"this"},{"word":"śhṛiṇu","meaning":"hear"}]'::jsonb, 'āhāraḥ—food; tu—indeed; api—even; sarvasya—of all; tri-vidhaḥ—of three kinds; bhavati—is; priyaḥ—dear; yajñaḥ—sacrifice; tapaḥ—austerity; tathā—and; dānam—charity; teṣhām—of them; bhedam—distinctions; imam—this; śhṛiṇu—hear'),
('09d55fa8-2f6a-58c3-90d7-4572ab1cf98d'::uuid, 17, 8, 603, 603, 'आयुःसत्त्वबलारोग्यसुखप्रीतिविवर्धनाः।रस्याः स्निग्धाः स्थिरा हृद्या आहाराः सात्त्विकप्रियाः।।17.8।।', 'āyuḥ-sattva-balārogya-sukha-prīti-vivardhanāḥ
rasyāḥ snigdhāḥ sthirā hṛidyā āhārāḥ sāttvika-priyāḥ', '[{"word":"āyuḥ sattva","meaning":"which promote longevity"},{"word":"bala","meaning":"strength"},{"word":"ārogya","meaning":"health"},{"word":"sukha","meaning":"happiness"},{"word":"prīti","meaning":"satisfaction"},{"word":"vivardhanāḥ","meaning":"increase"},{"word":"rasyāḥ","meaning":"juicy"},{"word":"snigdhāḥ","meaning":"succulent"},{"word":"sthirāḥ","meaning":"nourishing"},{"word":"hṛidyāḥ","meaning":"pleasing to the heart"},{"word":"āhārāḥ","meaning":"food"},{"word":"sāttvika","meaning":"priyāḥ—dear to those in the mode of goodness"}]'::jsonb, 'āyuḥ sattva—which promote longevity; bala—strength; ārogya—health; sukha—happiness; prīti—satisfaction; vivardhanāḥ—increase; rasyāḥ—juicy; snigdhāḥ—succulent; sthirāḥ—nourishing; hṛidyāḥ—pleasing to the heart; āhārāḥ—food; sāttvika-priyāḥ—dear to those in the mode of goodness'),
('d4155bb2-6f67-5465-8c29-70fc5140226a'::uuid, 17, 9, 604, 604, 'कट्वम्ललवणात्युष्णतीक्ष्णरूक्षविदाहिनः।आहारा राजसस्येष्टा दुःखशोकामयप्रदाः।।17.9।।', 'kaṭv-amla-lavaṇāty-uṣhṇa- tīkṣhṇa-rūkṣha-vidāhinaḥ
āhārā rājasasyeṣhṭā duḥkha-śhokāmaya-pradāḥ', '[{"word":"kaṭu","meaning":"bitter"},{"word":"amla","meaning":"sour"},{"word":"lavaṇa","meaning":"salty"},{"word":"ati","meaning":"uṣhṇa—very hot"},{"word":"tīkṣhṇa","meaning":"pungent"},{"word":"rūkṣha","meaning":"dry"},{"word":"vidāhinaḥ","meaning":"chiliful"},{"word":"āhārāḥ","meaning":"food"},{"word":"rājasasya","meaning":"to persons in the mode of passion"},{"word":"iṣhṭāḥ","meaning":"dear"},{"word":"duḥkha","meaning":"pain"},{"word":"śhoka","meaning":"grief"},{"word":"āmaya","meaning":"disease"},{"word":"pradāḥ","meaning":"produce"}]'::jsonb, 'kaṭu—bitter; amla—sour; lavaṇa—salty; ati-uṣhṇa—very hot; tīkṣhṇa—pungent; rūkṣha—dry; vidāhinaḥ—chiliful; āhārāḥ—food; rājasasya—to persons in the mode of passion; iṣhṭāḥ—dear; duḥkha—pain; śhoka—grief; āmaya—disease; pradāḥ—produce'),
('00a06d6b-74b1-5eb4-8913-196b68f88f30'::uuid, 17, 10, 605, 605, 'यातयामं गतरसं पूति पर्युषितं च यत्।उच्छिष्टमपि चामेध्यं भोजनं तामसप्रियम्।।17.10।।', 'yāta-yāmaṁ gata-rasaṁ pūti paryuṣhitaṁ cha yat
uchchhiṣhṭam api chāmedhyaṁ bhojanaṁ tāmasa-priyam', '[{"word":"yāta","meaning":"yāmam—stale foods"},{"word":"gata","meaning":"rasam—tasteless"},{"word":"pūti","meaning":"putrid"},{"word":"paryuṣhitam","meaning":"polluted"},{"word":"cha","meaning":"and"},{"word":"yat","meaning":"which"},{"word":"uchchhiṣhṭam","meaning":"left over"},{"word":"api","meaning":"also"},{"word":"cha","meaning":"and"},{"word":"amedhyam","meaning":"impure"},{"word":"bhojanam","meaning":"foods"},{"word":"tāmasa","meaning":"to persons in the mode of ignorance"},{"word":"priyam","meaning":"dear"}]'::jsonb, 'yāta-yāmam—stale foods; gata-rasam—tasteless; pūti—putrid; paryuṣhitam—polluted; cha—and; yat—which; uchchhiṣhṭam—left over; api—also; cha—and; amedhyam—impure; bhojanam—foods; tāmasa—to persons in the mode of ignorance; priyam—dear'),
('eb394f9c-4032-5958-acc1-41201a5febca'::uuid, 17, 11, 606, 606, 'अफलाकाङ्क्षिभिर्यज्ञो विधिदृष्टो य इज्यते।यष्टव्यमेवेति मनः समाधाय स सात्त्विकः।।17.11।।', 'aphalākāṅkṣhibhir yajño vidhi-driṣhṭo ya ijyate
yaṣhṭavyam eveti manaḥ samādhāya sa sāttvikaḥ', '[{"word":"aphala","meaning":"ākāṅkṣhibhiḥ—without expectation of any reward"},{"word":"yajñaḥ","meaning":"sacrifice"},{"word":"vidhi","meaning":"driṣhṭaḥ—that is in accordance with the scriptural injunctions"},{"word":"yaḥ","meaning":"which"},{"word":"ijyate","meaning":"is performed"},{"word":"yaṣhṭavyam","meaning":"eva-iti—ought to be offered"},{"word":"manaḥ","meaning":"mind"},{"word":"samādhāya","meaning":"with conviction"},{"word":"saḥ","meaning":"that"},{"word":"sāttvikaḥ","meaning":"of the nature of goodness"}]'::jsonb, 'aphala-ākāṅkṣhibhiḥ—without expectation of any reward; yajñaḥ—sacrifice; vidhi-driṣhṭaḥ—that is in accordance with the scriptural injunctions; yaḥ—which; ijyate—is performed; yaṣhṭavyam-eva-iti—ought to be offered; manaḥ—mind; samādhāya—with conviction; saḥ—that; sāttvikaḥ—of the nature of goodness'),
('45754dc4-f635-5074-8257-6aa2925cfea8'::uuid, 17, 12, 607, 607, 'अभिसंधाय तु फलं दम्भार्थमपि चैव यत्।इज्यते भरतश्रेष्ठ तं यज्ञं विद्धि राजसम्।।17.12।।', 'abhisandhāya tu phalaṁ dambhārtham api chaiva yat
ijyate bharata-śhreṣhṭha taṁ yajñaṁ viddhi rājasam', '[{"word":"abhisandhāya","meaning":"motivated by"},{"word":"tu","meaning":"but"},{"word":"phalam","meaning":"the result"},{"word":"dambha","meaning":"pride"},{"word":"artham","meaning":"for the sake of"},{"word":"api","meaning":"also"},{"word":"cha","meaning":"and"},{"word":"eva","meaning":"certainly"},{"word":"yat","meaning":"that which"},{"word":"ijyate","meaning":"is performed"},{"word":"bharata","meaning":"śhreṣhṭha—Arjun, the best of the Bharatas"},{"word":"tam","meaning":"that"},{"word":"yajñam","meaning":"sacrifice"},{"word":"viddhi","meaning":"know"},{"word":"rājasam","meaning":"in the mode of passion"}]'::jsonb, 'abhisandhāya—motivated by; tu—but; phalam—the result; dambha—pride; artham—for the sake of; api—also; cha—and; eva—certainly; yat—that which; ijyate—is performed; bharata-śhreṣhṭha—Arjun, the best of the Bharatas; tam—that; yajñam—sacrifice; viddhi—know; rājasam—in the mode of passion'),
('8dc98c4e-573d-5d37-8f89-6531f07bfba2'::uuid, 17, 13, 608, 608, 'विधिहीनमसृष्टान्नं मन्त्रहीनमदक्षिणम्।श्रद्धाविरहितं यज्ञं तामसं परिचक्षते।।17.13।।', 'vidhi-hīnam asṛiṣhṭānnaṁ mantra-hīnam adakṣhiṇam
śhraddhā-virahitaṁ yajñaṁ tāmasaṁ parichakṣhate', '[{"word":"vidhi","meaning":"hīnam—without scriptural direction"},{"word":"asṛiṣhṭa","meaning":"annam—without distribution of prasādam"},{"word":"mantra","meaning":"hīnam—with no chanting of the Vedic hymns"},{"word":"adakṣhiṇam","meaning":"with no remunerations to the priests"},{"word":"śhraddhā","meaning":"faith"},{"word":"virahitam","meaning":"without"},{"word":"yajñam","meaning":"sacrifice"},{"word":"tāmasam","meaning":"in the mode of ignorance"},{"word":"parichakṣhate","meaning":"is to be considered"}]'::jsonb, 'vidhi-hīnam—without scriptural direction; asṛiṣhṭa-annam—without distribution of prasādam; mantra-hīnam—with no chanting of the Vedic hymns; adakṣhiṇam—with no remunerations to the priests; śhraddhā—faith; virahitam—without; yajñam—sacrifice; tāmasam—in the mode of ignorance; parichakṣhate—is to be considered'),
('276d6a1c-42d9-5b10-82c8-76e653545806'::uuid, 17, 14, 609, 609, 'देवद्विजगुरुप्राज्ञपूजनं शौचमार्जवम्।ब्रह्मचर्यमहिंसा च शारीरं तप उच्यते।।17.14।।', 'deva-dwija-guru-prājña- pūjanaṁ śhaucham ārjavam
